import { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";

export default function Perfil() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [usuario, setUsuario] = useState(null);

  useEffect(() => {
    const buscarUsuario = async () => {
      try {
        const resposta = await axios.get(`http://localhost:3001/usuarios/${id}`);
        setUsuario(resposta.data);
      } catch (erro) {
        console.error("Erro ao buscar usuário:", erro);
      }
    };

    buscarUsuario();
  }, [id]);

  if (!usuario) return <p>Carregando...</p>;

  return (
    <div style={{ padding: "20px" }}>
      <h2>Perfil de Usuário</h2>

      <div style={{ marginBottom: "20px" }}>
        <button onClick={() => navigate("/")} style={{ background: "#007bff", color: "white", marginRight: 10 }}>Listar Usuários</button>
        <button onClick={() => navigate("/cadastrar")} style={{ background: "#28a745", color: "white", marginRight: 10 }}>Cadastrar</button>
        <button onClick={() => navigate(`/editar/${id}`)} style={{ background: "#ffc107", color: "black" }}>Editar</button>
      </div>

      <h3>Perfil de {usuario.nome}</h3>
      <img
        src={`http://localhost:3001${usuario.imagem}`}
        alt="Foto de perfil"
        style={{ width: 200, borderRadius: 10, marginBottom: 20 }}
      />
      <p><strong>Nome:</strong> {usuario.nome}</p>
      <p><strong>Idade:</strong> {usuario.idade}</p>
      <p><strong>Rua:</strong> {usuario.rua}</p>
      <p><strong>Bairro:</strong> {usuario.bairro}</p>
      <p><strong>Estado:</strong> {usuario.estado}</p>
      <p><strong>Biografia:</strong> {usuario.biografia}</p>
    </div>
  );
}
